WITH parsed AS (SELECT id, host, level, latency_ms, status_code, payload_json, context, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs) SELECT id, level, latency_ms, tier, LEAD(latency_ms) OVER (PARTITION BY level, tier ORDER BY latency_ms, id) AS next_latency_ms, LAG(status_code) OVER (PARTITION BY level, tier ORDER BY latency_ms, id) AS prev_status_code, LEAD(status_code) OVER (PARTITION BY level, tier ORDER BY latency_ms, id) AS next_status_code, ROW_NUMBER() OVER (PARTITION BY level, tier ORDER BY latency_ms, id) AS seq_no FROM parsed;
